<template><article v-if="recipe" class="recipe-card"><header><strong>{{recipeNames[lc][recipe.type]||recipe.type}}</strong><span v-if="recipe.station">{{nameOf(catalog?.items[recipe.station]||{id:recipe.station},lang)}}</span><span v-if="recipe.seconds!=null">{{recipe.seconds}} {{en?'seconds':'秒'}}</span></header><div class="recipe-flow"><div v-if="recipe.layout" class="recipe-grid"><div v-for="(slot,i) in recipe.layout" :key="i" class="recipe-slot" :class="{'is-core':i===4&&recipe.type==='reverie_dreams:gensokyo_altar'}"><IngredientSlot v-if="slot&&slot.id!=='minecraft:air'" :ingredient="slot"/></div></div><div v-else-if="recipe.shape" class="shape-grid" :style="{gridTemplateColumns:'repeat('+recipe.shape[0].length+', 1fr)'}"><template v-for="(row,y) in recipe.shape" :key="y"><span v-for="(cell,x) in row" :key="x" :class="{filled:cell===1||cell===true||cell==='#'}"></span></template></div><div v-else class="recipe-ingredients"><IngredientSlot v-for="(input,i) in recipe.inputs" :key="i" :ingredient="input"/></div><span class="recipe-arrow" aria-hidden="true">→</span><div class="recipe-result"><McItem v-if="recipe.output?.id" :id="recipe.output.id" :stack="recipe.output" :count="recipe.output.count" :size="48" :show-name="true"/><span v-else>{{en?'Special operation':'特殊操作配方'}}</span></div></div><small v-if="recipe.type==='reverie_dreams:gensokyo_altar'">{{en?'The highlighted center is the core. Surrounding slots match the in-game altar interface.':'高亮中心为核心槽，外围材料按游戏祭坛界面排列。'}}</small><p v-if="recipe.virtual" class="muted">{{en?'Generated operation: the result inherits and changes the input stack’s properties. This icon is the item type, not fixed final stats.':'此项是运行时生成的操作：结果会继承并改变输入物品属性。图标表示物品类型，不代表固定的最终数值。'}}</p><p v-if="recipe.timeNote==='kitchen'" class="muted">{{en?'Base time: manual GUI adds 1.25 s; Fast Recipe Book adds 0.25 s per base ingredient. Divide by the kitchenware progress multiplier.':'这里是基础时间：手动界面加 1.25 秒；快速食谱加基础食材种数 × 0.25 秒。再除以厨具进度倍率。'}}</p><details class="recipe-source"><summary>{{en?'Recipe ID and source':'配方编号与来源'}}</summary><code>{{recipe.id}}</code><p>{{recipe.source}}</p></details></article></template>
<script setup lang="ts">
import{computed,ref,onMounted}from'vue';import{useData}from'vitepress';import{getData,nameOf,recipeNames,locale}from'../lib/wiki';import IngredientSlot from'./IngredientSlot.vue';import McItem from'./McItem.vue';
const props=defineProps<{recipe:any}>();const{lang}=useData();const lc=computed(()=>locale(lang.value)),en=computed(()=>lc.value==='en');const catalog=ref<any>();onMounted(async()=>{catalog.value=await getData()});
</script>
